mapper.select:
SELECT * FROM inventory_adjust
WHERE deleted = 0

    AND adjust_type = #{adjustType}


    AND status = #{status}


    AND warehouse_id = #{warehouseId}


    AND (adjust_code LIKE CONCAT('%', #{keyword}, '%')
         OR reference_no LIKE CONCAT('%', #{keyword}, '%'))


    AND apply_time >= #{startDate}


    AND apply_time <= #{endDate}

ORDER BY create_time DESC
